export const getKillsControllerGetMemberKillsUrl = ({ guildId, memberId }: KillsControllerGetMemberKillsPathParameters,
    params?: KillsControllerGetMemberKillsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    const explodeParameters = ["npcTypes"];

    if (Array.isArray(value) && explodeParameters.includes(key)) {
      value.forEach((v) => {
        normalizedParams.append(key, v === null ? 'null' : String(v));
      });
      return;
    }

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/guilds/${guildId}/stats/kills/members/${memberId}?${stringifiedParams}` : `/guilds/${guildId}/stats/kills/members/${memberId}`
}

